/// A vector in [color] (the ambient icon colour by default), [size] on its longer side.
class NDVectorIcon extends StatelessWidget {
  const NDVectorIcon(this.vector, {super.key, this.size = 24, this.color});

  NDVectorIcon.icon(NDIcon icon, {Key? key, double size = 24, Color? color})
      : this(icon.vector, key: key, size: size, color: color);

  final NDVector vector;
  final double size;
  final Color? color;

  @override
  Widget build(BuildContext context) {
    final scale = size / (vector.width > vector.height ? vector.width : vector.height);
    return ExcludeSemantics(
      child: CustomPaint(
        size: Size(vector.width * scale, vector.height * scale),
        painter: NDVectorPainter(vector, color ?? IconTheme.of(context).color ?? const Color(0xFF000000)),
      ),
    );
  }
}

/// Paints a vector fitted into the canvas, centred with its aspect kept.
class NDVectorPainter extends CustomPainter {
  NDVectorPainter(this.vector, this.color);

  final NDVector vector;
  final Color color;

  @override
  void paint(Canvas canvas, Size size) {
    final scale = size.width / vector.width < size.height / vector.height
        ? size.width / vector.width
        : size.height / vector.height;
    final dx = (size.width - vector.width * scale) / 2 - vector.minX * scale;
    final dy = (size.height - vector.height * scale) / 2 - vector.minY * scale;
    for (final shape in vector.shapes) {
      final path = Path()..fillType = shape.evenOdd ? PathFillType.evenOdd : PathFillType.nonZero;
      for (final s in shape.segments) {
        switch (s.op) {
          case NDPathOp.move:
            path.moveTo(s.a * scale + dx, s.b * scale + dy);
          case NDPathOp.line:
            path.lineTo(s.a * scale + dx, s.b * scale + dy);
          case NDPathOp.curve:
            path.cubicTo(s.a * scale + dx, s.b * scale + dy, s.c * scale + dx, s.d * scale + dy,
                s.e * scale + dx, s.f * scale + dy);
          case NDPathOp.close:
            path.close();
        }
      }
      if (shape.fill) canvas.drawPath(path, Paint()..color = color);
      if (shape.stroke) {
        canvas.drawPath(
          path,
          Paint()
            ..color = color
            ..style = PaintingStyle.stroke
            ..strokeWidth = shape.strokeWidth * scale
            ..strokeCap = shape.lineCap
            ..strokeJoin = shape.lineJoin,
        );
      }
    }
  }

  @override
  bool shouldRepaint(NDVectorPainter oldDelegate) =>
      oldDelegate.vector != vector || oldDelegate.color != color;
}
